import{_ as e,o as l,c as a,S as c}from"./chunks/framework.c4402963.js";const u=JSON.parse('{"title":"与原生微信小程序版的差异","description":"","frontmatter":{},"headers":[],"relativePath":"uniapp/platform-diff.md","filePath":"uniapp/platform-diff.md"}'),t={name:"uniapp/platform-diff.md"};function s(d,o,r,p,n,i){return l(),a("div",null,[...o[0]||(o[0]=[c(`<h1 id="与原生微信小程序版的差异" tabindex="-1">与原生微信小程序版的差异 <a class="header-anchor" href="#与原生微信小程序版的差异" aria-label="Permalink to &quot;与原生微信小程序版的差异&quot;">​</a></h1><p>uni-app 版（<code>coolui-scroller-uni</code>）的组件能力、交互效果与原生微信小程序版保持一致，<strong>props 与配置项可直接对照原生微信小程序版文档</strong>。差异集中在下面两类：与原生微信小程序版的写法差异、各端（小程序 / H5 / App）的运行差异。</p><h2 id="一、与原生微信小程序版的写法差异" tabindex="-1">一、与原生微信小程序版的写法差异 <a class="header-anchor" href="#一、与原生微信小程序版的写法差异" aria-label="Permalink to &quot;一、与原生微信小程序版的写法差异&quot;">​</a></h2><table><thead><tr><th>项</th><th>原生微信小程序版</th><th>uni-app 版</th></tr></thead><tbody><tr><td>组件标签</td><td><code>scroller</code>、<code>refresh</code>、<code>item</code>…（可自定义 tag 名）</td><td>统一 <code>coolui-scroller-*</code> 前缀，如 <code>coolui-scroller-refresh</code></td></tr><tr><td>事件</td><td><code>bind:refresh</code> / <code>bind:loadmore</code></td><td><code>@refresh</code> / <code>@loadmore</code></td></tr><tr><td>受控属性</td><td>直接改 data</td><td>通过 <code>@update:propName</code> 同步，如 sort-item 的 <code>@update:value</code></td></tr><tr><td>保留字属性</td><td>search 组件用 <code>key</code></td><td>改名为 <code>keyword</code>，用 <code>@update:keyword</code> 同步</td></tr><tr><td>组件通信</td><td>小程序 <code>relations</code> 关联父子组件</td><td>Vue <code>provide/inject</code></td></tr><tr><td>长列表</td><td><code>scroll-page</code>（整页占位）</td><td><code>coolui-scroller-page</code>（旧方案）+ <code>coolui-scroller-longlist</code>（窗口化，推荐）</td></tr><tr><td>类型</td><td>—</td><td><code>.vue</code> + <code>types.ts</code>，可 <code>import type { CooluiScrollerProps } from &#39;coolui-scroller-uni/types&#39;</code></td></tr></tbody></table><p>需要在组件之间通信的嵌套关系（保持层级即可，无需手动配置）：</p><ul><li><code>coolui-scroller</code> → <code>coolui-scroller-refresh</code> / <code>coolui-scroller-back-to-top</code></li><li><code>coolui-scroller-refresh</code> → <code>coolui-scroller-parallax</code></li><li><code>coolui-scroller-nav-pannel</code> → <code>coolui-scroller</code></li><li><code>coolui-scroller-sort</code> → <code>coolui-scroller-sort-item</code></li><li><code>coolui-scroller-second-floor</code> → <code>coolui-scroller-second-floor-refresh</code> / <code>coolui-scroller-nav-bar</code></li></ul><h2 id="二、各端运行差异" tabindex="-1">二、各端运行差异 <a class="header-anchor" href="#二、各端运行差异" aria-label="Permalink to &quot;二、各端运行差异&quot;">​</a></h2><h3 id="h5-内置导航栏会额外占高" tabindex="-1">H5 内置导航栏会额外占高 <a class="header-anchor" href="#h5-内置导航栏会额外占高" aria-label="Permalink to &quot;H5 内置导航栏会额外占高&quot;">​</a></h3><p>uni-app 在 H5 端会额外渲染内置导航栏（高度就是 CSS 变量 <code>--window-top</code>，默认 44px），而 <code>pages.json</code> 里的 <code>disableScroll</code> <strong>只在小程序端生效</strong>。于是全屏页写 <code>height: 100vh</code> 时会比可视区高出一截，出现页面级滚动条（小程序端一直正常，所以就容易漏）。</p><div class="language-scss"><button title="Copy Code" class="copy"></button><span class="lang">scss</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#676E95;font-style:italic;">/* #ifdef H5 */</span></span>
<span class="line"><span style="color:#89DDFF;">.</span><span style="color:#FFCB6B;">page</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#A6ACCD;">  </span><span style="color:#B2CCD6;">height</span><span style="color:#89DDFF;">:</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">calc</span><span style="color:#89DDFF;">(</span><span style="color:#F78C6C;">100vh</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">-</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">var</span><span style="color:#89DDFF;">(</span><span style="color:#A6ACCD;">--window-top</span><span style="color:#89DDFF;">,</span><span style="color:#A6ACCD;"> </span><span style="color:#F78C6C;">0px</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">-</span><span style="color:#A6ACCD;"> </span><span style="color:#82AAFF;">var</span><span style="color:#89DDFF;">(</span><span style="color:#A6ACCD;">--window-bottom</span><span style="color:#89DDFF;">,</span><span style="color:#A6ACCD;"> </span><span style="color:#F78C6C;">0px</span><span style="color:#89DDFF;">));</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">/* #endif */</span></span></code></pre></div><ul><li>用 <code>--window-top</code> / <code>--window-bottom</code>（tabbar）而不是写死 44px；默认值 <code>0px</code> 兜底，变量缺失时不会反向变矮。</li><li><code>#ifdef H5</code> 包裹后，这段样式在小程序 / App 端构建时会被剥离，行为不变。</li><li>自定义导航栏（<code>navigationStyle: custom</code>）的页面 <code>--window-top</code> 为 0，无需处理。</li></ul><h3 id="插槽与样式作用域" tabindex="-1">插槽与样式作用域 <a class="header-anchor" href="#插槽与样式作用域" aria-label="Permalink to &quot;插槽与样式作用域&quot;">​</a></h3><p>小程序端组件插槽<strong>不是作用域插槽</strong>，且页面里 <code>scoped</code> 样式穿不进组件插槽。所以：</p><ul><li>页面里给插槽内容写样式时，选择器要落在插槽内容本身（例如给内容加自己的 class），不要指望 <code>.coolui-scroller .item</code> 这类跨组件选择器；</li><li>若要统一列表项间距、内边距，写在组件/列表项自身的样式上，或给插槽内容加 class 后再写。</li></ul><h3 id="下拉刷新动画与「原生效果」" tabindex="-1">下拉刷新动画与「原生效果」 <a class="header-anchor" href="#下拉刷新动画与「原生效果」" aria-label="Permalink to &quot;下拉刷新动画与「原生效果」&quot;">​</a></h3><p><code>type: &#39;default&#39;</code> 会走小程序原生的下拉样式（三个圆点动画）。<strong>同一个组件、同一个 type，两个页面观感不同，多半是刷新配置不一致</strong>：<code>background.height</code>（下拉行程）大于 <code>height</code>（刷新自身高度）时，松手先回落到 <code>height</code> 显示加载动画、刷新完成后再整体回弹，也就是「两段回弹」的弹性感；不设置时行程很快就饱和，只剩单段回弹，手感偏硬。</p><h3 id="app-端" tabindex="-1">App 端 <a class="header-anchor" href="#app-端" aria-label="Permalink to &quot;App 端&quot;">​</a></h3><p>组件按源码参与编译，App 端与小程序端表现一致；H5 的高度处理同样适用于 App 端内嵌 WebView 的场景。App 资源包用 <code>npm run build:app</code> 产出，安装包需要在 HBuilderX 里云打包生成。</p><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/coolui-scroller/v4/advanced/faq.html">常见问题</a>：下拉没弹性、页面滚动条、列表间距等</li><li><a href="/coolui-scroller/v4/uniapp/install.html">安装与引入</a> / <a href="/coolui-scroller/v4/uniapp/quickstart.html">快速开始</a></li></ul>`,20)])])}const f=e(t,[["render",s]]);export{u as __pageData,f as default};
